import { RawCourseVersion } from "./types";

/**
 * Raw course versions as they might come back from a single SIS pull.
 *
 * Cases baked in on purpose:
 *
 *  1. COMPSCI 61A / 61B  - plain ACTIVE-only courses, no collision. Sanity baseline.
 *  2. MATH 1A            - same courseId, SAME subject/number, one ACTIVE + one
 *                          FUTURE record (SIS re-issued a course action that
 *                          didn't change the catalog number). These collide and
 *                          must collapse to exactly one canonical row.
 *  3. ECON 1 / ECON 1A   - a genuine renumbering: same courseId, but the FUTURE
 *                          record has a DIFFERENT subject/number than the
 *                          ACTIVE record. These do NOT collide -- both should
 *                          survive as separate rows (old number now, new
 *                          number later), because they describe different
 *                          catalog entries.
 *  4. STAT 134           - FUTURE-only. Brand new course, approved but not
 *                          in effect yet. No ACTIVE version exists at all.
 *  5. PHYSICS 137A        - a data-quality edge case: SIS returned the SAME
 *                          (courseId, subject, number, FUTURE) combination
 *                          twice, with different fromDates. Must still
 *                          collapse to exactly one row, deterministically.
 */
